def _backfill_search_text() -> None:
    """Searchable text of existing submissions (non-sensitive answers only)."""
    from app.answers import search_text
    from app.schemas.form import Form

    bind = op.get_bind()
    versions = {
        vid: Form.model_validate(schema)
        for vid, schema in bind.execute(sa.text("SELECT id, schema FROM form_versions"))
    }
    rows = bind.execute(sa.text("SELECT id, form_version_id, data FROM submissions")).all()
    for sid, vid, data in rows:
        form = versions.get(vid)
        if form is None:
            continue
        bind.execute(
            sa.text("UPDATE submissions SET search_text = :t WHERE id = :id"),
            {"t": search_text(form, data or {}), "id": sid},
        )


